From 40984c37be32aaa7e6a911f2bf7b36ca737d30bb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:54:09 +0100
Subject: [PATCH] startplasma: don't overwrite XKB_DEFAULT_* variables that are
 already set

On Wayland, startplasma exported the keyboard settings from localed as
XKB_DEFAULT_* even when the user had already set them, e.g. in .profile,
so the system default won. Only set each variable when it isn't set yet.

BUG: 447203
---
 startkde/startplasma.cpp | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..3a6697a6c7 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -830,7 +830,7 @@ int main(int argc, char **argv)

             auto queryAndSet = [&result](const char *var, const QString &value) {
                 const auto r = result.value(value).toString();
-                if (!r.isEmpty()) {
+                if (!r.isEmpty() && !qEnvironmentVariableIsSet(var)) {
                     qputenv(var, r.toUtf8());
                 }
             };
-- 
